import type { ContentCatalogue } from '../content'

export const ES_PAGEGUIDES: ContentCatalogue = {
  "guide.construct.lede": { fp: "bjjn6o", text: "Busca construcciones gramaticales en vez de palabras: cada infinitivo articular, cada genitivo absoluto." },
  "guide.construct.r0": { fp: "1v8jdpw", text: "Búsqueda: encontrar palabras y frases" },
  "guide.construct.s0.b": { fp: "1hskmd7", text: "La búsqueda corriente encuentra palabras. Esta encuentra formas: una preposición que rige un caso determinado, un participio que concuerda con un sustantivo, un subjuntivo tras ἵνα. Estás describiendo un patrón, y la búsqueda devuelve cada lugar del corpus que lo cumple, en el Nuevo Testamento griego, la Septuaginta, la Biblia hebrea y el resto de la biblioteca." },
  "guide.construct.s0.h": { fp: "1ctdehd", text: "Qué la hace distinta" },
  "guide.construct.s1.b": { fp: "jbnxqd", text: "Los ejemplos predefinidos son la vía más rápida de entrar, y también de aprender el lenguaje de consulta: elige uno parecido a lo que buscas, ejecútalo y modifícalo. Construir una consulta desde cero es posible, pero rara vez es el camino más corto." },
  "guide.construct.s1.h": { fp: "hp3x7p", text: "Empieza por un ejemplo listo" },
  "guide.construct.s2.b": { fp: "1kq7anw", text: "Los términos pueden exigir concordancia entre sí, excluir un rasgo en lugar de exigirlo, y limitarse a una oración o a una distancia. Buscar en todos los textos a la vez da una distribución en vez de una lista de aciertos, lo cual sirve para mostrar que una construcción se concentra en un autor." },
  "guide.construct.s2.h": { fp: "l4gte4", text: "Afinar una consulta" },
  "guide.construct.s3.b": { fp: "kt2e5m", text: "La distancia entre palabras se cuenta en huecos, no en palabras: dos palabras a cada lado de un término son una distancia de tres, no de dos. Si una consulta devuelve menos de lo esperado, ampliar la distancia en uno suele ser la solución." },
  "guide.construct.s3.h": { fp: "4fcpwf", text: "Algo que conviene tener en cuenta" },
  "guide.construct.title": { fp: "osti0m", text: "Búsqueda de construcciones" },
  "guide.exegesis.hebrew.s0.b": { fp: "1rr5nul", text: "No son una secuencia que haya que recorrer. Cada una es una pregunta distinta que puedes hacerle a los mismos versículos: cómo se analiza, cómo se divide, dónde se cuenta esta historia dos veces, qué leen las versiones antiguas, qué reutiliza la propia Escritura, cómo se ha recibido el versículo, qué han dicho los comentaristas y qué piensas tú. Muévete entre ellas según lo pida el pasaje." },
  "guide.exegesis.hebrew.s0.h": { fp: "f7okiv", text: "Cómo se relacionan las pestañas" },
  "guide.exegesis.hebrew.s1.b": { fp: "f6tlz0", text: "Una sola referencia mueve todas las pestañas. Al cambiarla se mueven todas las vistas a la vez, de modo que puedes analizar un versículo, luego ponerlo junto a Crónicas y luego leer su targum sin volver a escribir nada." },
  "guide.exegesis.hebrew.s1.h": { fp: "m25tkl", text: "El cuadro del pasaje" },
  "guide.exegesis.hebrew.s2.b": { fp: "yo16ea", text: "Cada pestaña tiene su propio menú con los ajustes que le corresponden: tamaño del texto, visibilidad de las fuentes y los avisos de derechos de los datos que esa pestaña muestra. En el teléfono, ese mismo menú es también donde se cambia de pestaña." },
  "guide.exegesis.hebrew.s2.h": { fp: "1dmtvdr", text: "Ajustes de cada vista" },
  "guide.exegesis.lede": { fp: "1hv3d63", text: "Nueve miradas sobre un mismo pasaje: pon una referencia en el cuadro de arriba y todas las pestañas la siguen." },
  "guide.exegesis.r0": { fp: "o3zgso", text: "Lector: leer de corrido en vez de esto" },
  "guide.exegesis.s0.b": { fp: "yw926c", text: "No son una secuencia que haya que recorrer. Cada una es una pregunta distinta que puedes hacerle a los mismos versículos: cómo se analiza, cómo se divide, quién más cuenta esta historia, qué leen los manuscritos, qué está citando, cómo se argumenta, qué han dicho otros y qué piensas tú. Muévete entre ellas según lo pida el pasaje." },
  "guide.exegesis.s0.h": { fp: "f7okiv", text: "Cómo se relacionan las pestañas" },
  "guide.exegesis.s1.b": { fp: "10ssi8v", text: "Una sola referencia mueve las nueve pestañas. Al cambiarla se mueven todas las vistas a la vez, de modo que puedes analizar un versículo, luego mirar sus manuscritos y luego su trasfondo veterotestamentario sin volver a escribir nada." },
  "guide.exegesis.s1.h": { fp: "m25tkl", text: "El cuadro del pasaje" },
  "guide.exegesis.s2.b": { fp: "yo16ea", text: "Cada pestaña tiene su propio menú con los ajustes que le corresponden: tamaño del texto, visibilidad de las fuentes y los avisos de derechos de los datos que esa pestaña muestra. En el teléfono, ese mismo menú es también donde se cambia de pestaña." },
  "guide.exegesis.s2.h": { fp: "1dmtvdr", text: "Ajustes de cada vista" },
  "guide.exegesis.title": { fp: "u8bhek", text: "El taller de exégesis" },
  "guide.exegesis:allusions.hebrew.lede": { fp: "1a4o7cf", text: "Rastrea cómo la Biblia hebrea se reutiliza a sí misma, con la evidencia sopesada delante de ti." },
  "guide.exegesis:allusions.hebrew.s0.b": { fp: "fufe58", text: "La Escritura cita a la Escritura mucho antes de que lo haga el Nuevo Testamento: la fórmula de la gracia de Éxodo 34 resuena por los Profetas y los Salmos, y Génesis 1 está detrás del Salmo 8. Toca las palabras cargadas de tu pasaje y la búsqueda ordena el resto de la Biblia hebrea según la fuerza con que las comparte." },
  "guide.exegesis:allusions.hebrew.s0.h": { fp: "4twk8j", text: "Alusión interna a la Biblia" },
  "guide.exegesis:allusions.hebrew.s1.b": { fp: "goq5lo", text: "Compartir una palabra común no prueba nada; compartir una rara, o un par raro en secuencia, sí es prueba. Las palabras punteadas son las raras, y la búsqueda pondera las coincidencias en consecuencia: el mismo método que se usa para las alusiones neotestamentarias a la Septuaginta, apuntado al hebreo." },
  "guide.exegesis:allusions.hebrew.s1.h": { fp: "1rulspw", text: "La rareza es el argumento" },
  "guide.exegesis:allusions.hebrew.s2.b": { fp: "1bqxv36", text: "La lista de comprobación junto a los resultados recorre las pruebas habituales. La aplicación completa lo que se puede medir; si el paralelo es una alusión, una fórmula o una coincidencia sigue siendo tu juicio, que es la destreza que se está practicando." },
  "guide.exegesis:allusions.hebrew.s2.h": { fp: "9nrztz", text: "El caso lo construyes tú" },
  "guide.exegesis:allusions.lede": { fp: "rsf1pv", text: "Rastrea las alusiones a la Septuaginta detrás de un pasaje neotestamentario, siguiendo el método de Allison." },
  "guide.exegesis:allusions.s0.b": { fp: "aem9ga", text: "Selecciona las palabras que te parezcan cargadas —o acepta la sugerencia, que escoge las que son bastante distintivas en la Septuaginta como para contar como prueba— y busca. Los candidatos vuelven ordenados, primero los más fuertes." },
  "guide.exegesis:allusions.s0.h": { fp: "ato2v2", text: "Cómo usarla" },
  "guide.exegesis:allusions.s1.b": { fp: "p5oj52", text: "Compartir una palabra rara es prueba; compartir una común no lo es. La clasificación pondera cada palabra compartida según lo rara que sea en la Septuaginta y busca series de palabras que aparezcan en el mismo orden, que es lo que distingue una cita de una coincidencia." },
  "guide.exegesis:allusions.s1.h": { fp: "7xd4k2", text: "Por qué importa la rareza" },
  "guide.exegesis:allusions.s2.b": { fp: "1g6k81r", text: "Las pruebas de Allison van al costado. La aplicación responde las dos que puede medir —si la fuente se nombra y si hay palabras trasplantadas— y te deja el resto, porque son juicios sobre circunstancia y estructura que ningún recuento de palabras resuelve." },
  "guide.exegesis:allusions.s2.h": { fp: "d69e90", text: "La lista de comprobación" },
  "guide.exegesis:allusions.title": { fp: "3tao4h", text: "Exégesis · Alusiones" },
  "guide.exegesis:backgrounds.hebrew.lede": { fp: "n7563m", text: "Cómo se recibió este pasaje: adónde lo llevaron la Escritura y sus primeros lectores." },
  "guide.exegesis:backgrounds.hebrew.s0.b": { fp: "1sphqsc", text: "En un pasaje del Antiguo Testamento el tráfico va casi siempre en sentido contrario: en vez de preguntar de qué se sirve el versículo, esta vista reúne lo que se sirve de él, es decir, cada cita neotestamentaria que hay en el aparato, abierta en el mismo lugar y con la nota que explica la conexión." },
  "guide.exegesis:backgrounds.hebrew.s0.h": { fp: "1f8e1rp", text: "Recepción, no trasfondo" },
  "guide.exegesis:backgrounds.hebrew.s1.b": { fp: "evm34v", text: "Para el Pentateuco e Isaías, cada capítulo enlaza su targum: la versión interpretativa aramea que se leía en la sinagoga. Donde el targum amplía o suaviza el hebreo, estás viendo trabajar al comentario continuo más antiguo que existe." },
  "guide.exegesis:backgrounds.hebrew.s1.h": { fp: "1vcrq43", text: "Los targumes" },
  "guide.exegesis:backgrounds.hebrew.s2.b": { fp: "2xvqoy", text: "Las citas de la Misná, el Talmud, Josefo, Filón y el resto se abren en el mismo lugar, y toda la biblioteca se puede buscar por una frase: útil cuando un giro suena formulario y quieres saber de quién era la fórmula." },
  "guide.exegesis:backgrounds.hebrew.s2.h": { fp: "3h1ytb", text: "La biblioteca" },
  "guide.exegesis:backgrounds.hebrew.title": { fp: "jwnt2o", text: "Exégesis · Recepción" },
  "guide.exegesis:backgrounds.lede": { fp: "1yzkbbf", text: "Lo que este pasaje cita, evoca o con lo que comparte un mundo." },
  "guide.exegesis:backgrounds.s0.b": { fp: "17rmjx8", text: "El aparato reúne las citas del Antiguo Testamento y los paralelos señalados en las obras de referencia habituales, para que veas de un vistazo de qué se está sirviendo un versículo." },
  "guide.exegesis:backgrounds.s0.h": { fp: "1ky72ss", text: "Referencias cruzadas" },
  "guide.exegesis:backgrounds.s1.b": { fp: "1amdn5w", text: "Las citas de Josefo, Filón, los Padres apostólicos, los targumes, la Misná y el resto se abren en el mismo lugar. También puedes buscar una frase en toda la biblioteca, algo útil cuando un giro suena idiomático y quieres saber si lo es." },
  "guide.exegesis:backgrounds.s1.h": { fp: "1fj6rm3", text: "La biblioteca de trasfondo" },
  "guide.exegesis:backgrounds.s2.b": { fp: "1482gwq", text: "Un paralelo no es una fuente. Que dos textos compartan la redacción puede significar dependencia, una tradición común, o simplemente que ambos escriben griego corriente sobre un asunto común. El aparato encuentra candidatos; el argumento sigue siendo tuyo." },
  "guide.exegesis:backgrounds.s2.h": { fp: "1fa4wit", text: "Una advertencia" },
  "guide.exegesis:backgrounds.title": { fp: "9nwfgc", text: "Exégesis · Trasfondo" },
  "guide.exegesis:commentary.hebrew.lede": { fp: "11uqeym", text: "El hebreo a la izquierda y Keil y Delitzsch siguiéndote a la derecha." },
  "guide.exegesis:commentary.hebrew.s0.b": { fp: "ow7jqx", text: "El hebreo vocalizado se desplaza a la izquierda, con análisis al hacer clic; el panel del comentario sigue el versículo en el que estás. Para el Antiguo Testamento el comentario es el de Keil y Delitzsch, que sigue siendo el comentario erudito más completo de toda la Biblia hebrea en dominio público, y lo bastante filológico como para recompensar su lectura con el texto abierto." },
  "guide.exegesis:commentary.hebrew.s0.h": { fp: "1sgp8en", text: "Leer con el comentario" },
  "guide.exegesis:commentary.hebrew.s1.b": { fp: "1i5onzq", text: "Keil y Delitzsch tratan a menudo varios versículos como una sola unidad, así que la nota que se muestra para un versículo puede empezar unos versículos antes; y algunos tramos (las genealogías sobre todo) no tienen nota versículo por versículo. Al hacer clic en un versículo vecino se encuentra la discusión." },
  "guide.exegesis:commentary.hebrew.s1.h": { fp: "1wf6rn4", text: "Sus costumbres" },
  "guide.exegesis:commentary.lede": { fp: "1nf2x08", text: "Comentario de dominio público sobre el pasaje abierto." },
  "guide.exegesis:commentary.s0.b": { fp: "7u6rf7", text: "El comentario sigue el pasaje del cuadro de arriba. El tamaño del texto y el interlineado se pueden ajustar para lecturas largas, y el aviso de derechos de lo que se está mostrando está en el menú." },
  "guide.exegesis:commentary.s0.h": { fp: "636llc", text: "Cómo usarlo" },
  "guide.exegesis:commentary.s1.b": { fp: "1bl08wl", text: "Son obras antiguas, de licencia libre, y en algunos puntos se les notan los años. Sirven sobre todo por las preguntas que plantean y los paralelos que reúnen, más que como veredicto cerrado." },
  "guide.exegesis:commentary.s1.h": { fp: "t1l485", text: "Qué esperar" },
  "guide.exegesis:commentary.title": { fp: "11xan0y", text: "Exégesis · Comentario" },
  "guide.exegesis:notes.lede": { fp: "1698ubr", text: "Tus propias notas, unidas a los versículos a los que pertenecen." },
  "guide.exegesis:notes.s0.b": { fp: "1d2ji97", text: "Una nota pertenece a un versículo, así que vuelve cada vez que regresas a ese versículo en cualquier parte de la aplicación: los iconos de nota del Lector y los de este taller son las mismas notas. Las carpetas mantienen un proyecto largo separado de la lectura diaria." },
  "guide.exegesis:notes.s0.h": { fp: "c4g32x", text: "Cómo se unen las notas" },
  "guide.exegesis:notes.s1.b": { fp: "u6igmc", text: "El tamaño del texto y el interlineado son ajustables y se aplican a la vez a todos los paneles de notas, de modo que un ajuste elegido aquí te acompaña al Lector." },
  "guide.exegesis:notes.s1.h": { fp: "snyd9r", text: "Comodidad de lectura" },
  "guide.exegesis:notes.title": { fp: "p7ln88", text: "Exégesis · Notas" },
  "guide.exegesis:phrasing.hebrew.lede": { fp: "1w667nk", text: "Ve el pasaje dispuesto por oraciones y sintagmas, de derecha a izquierda, en vez de como una hilera de palabras." },
  "guide.exegesis:phrasing.hebrew.s0.b": { fp: "1xlj0mu", text: "La sangría refleja el análisis de oraciones y sintagmas de la Biblia hebrea etiquetada: los elementos subordinados quedan debajo de aquello que modifican, y todo el árbol se refleja de derecha a izquierda con el texto. Donde una palabra escrita son en realidad dos —una preposición soldada a su sustantivo—, las piezas aparecen donde las pone la sintaxis, cada una con su glosa." },
  "guide.exegesis:phrasing.hebrew.s0.h": { fp: "rzv62g", text: "Qué estás viendo" },
  "guide.exegesis:phrasing.hebrew.s1.b": { fp: "1o6722v", text: "Esta es la vista para «¿dónde se rompe la cadena de wayyiqtol y qué se ha antepuesto?», las preguntas de las que depende la narrativa hebrea. Una etiqueta en lo alto de cada recuadro da el orden de los constituyentes (V-S-O y sus variantes), de modo que las alteraciones del orden de palabras se ven de un vistazo." },
  "guide.exegesis:phrasing.hebrew.s1.h": { fp: "636llc", text: "Para qué sirve" },
  "guide.exegesis:phrasing.hebrew.s2.b": { fp: "aqlh43", text: "La vista Diagrama (la predeterminada; el selector de arriba a la izquierda cambia al árbol sintáctico) convierte cada oración en un lienzo: arrastra las palabras hebreas adonde las ponga tu análisis y usa las herramientas de línea, corchete y etiqueta para marcar las conexiones. Arrastra un recuadro alrededor de varias palabras para moverlas juntas, haz clic en una línea trazada para moverla o rehacerla, y deshaz cualquier desliz. Tu disposición se guarda mientras trabajas, y el enlace «Cómo se hace» abre un ejemplo resuelto." },
  "guide.exegesis:phrasing.hebrew.s2.h": { fp: "19ypuc1", text: "Hacer tu propio diagrama" },
  "guide.exegesis:phrasing.lede": { fp: "105rwqp", text: "Ve el pasaje dispuesto por oraciones y sintagmas, o diagrámalo tú mismo." },
  "guide.exegesis:phrasing.s0.b": { fp: "twik5i", text: "La sangría refleja el árbol sintáctico de los datos del banco de árboles: los elementos subordinados quedan debajo de aquello que modifican. Las oraciones largas y enredadas —Efesios 1, por ejemplo— se abarcan mucho mejor en cuanto la subordinación se ve." },
  "guide.exegesis:phrasing.s0.h": { fp: "rzv62g", text: "Qué estás viendo" },
  "guide.exegesis:phrasing.s1.b": { fp: "17ohqiw", text: "Esta es la vista a la que hay que acudir cuando la pregunta es «¿cuál es el verbo principal y qué cuelga de él?». Es también la forma más rápida de descubrir que un sintagma que dabas por referido a una cosa en realidad modifica otra." },
  "guide.exegesis:phrasing.s1.h": { fp: "636llc", text: "Para qué sirve" },
  "guide.exegesis:phrasing.s2.b": { fp: "1kmxhwd", text: "La vista Diagrama (la predeterminada; el selector de arriba a la izquierda cambia al árbol sintáctico) convierte cada oración en un lienzo: arrastra las palabras griegas adonde las ponga tu análisis y usa las herramientas de línea, corchete y etiqueta para marcar la estructura. Arrastra un recuadro alrededor de varias palabras para moverlas juntas, haz clic en una línea trazada para moverla o rehacerla, y deshaz cualquier desliz. Tu disposición se guarda mientras trabajas, y el enlace «Cómo se hace» abre un ejemplo resuelto." },
  "guide.exegesis:phrasing.s2.h": { fp: "19ypuc1", text: "Hacer tu propio diagrama" },
  "guide.exegesis:phrasing.title": { fp: "4i7efd", text: "Exégesis · Diagramación" },
  "guide.exegesis:rhetoric.hebrew.lede": { fp: "1ecf6qz", text: "Las figuras que operan en un pasaje hebreo, incluidas las que solo el hebreo tiene." },
  "guide.exegesis:rhetoric.hebrew.s0.b": { fp: "g536b7", text: "El hebreo vocalizado va a la izquierda, con análisis al hacer clic; las figuras halladas en cada versículo, en el centro; y a la derecha una explicación con Keil y Delitzsch sobre ese versículo debajo. Las figuras vienen de Bullinger, que catalogó la Biblia entera y no solo el Nuevo Testamento." },
  "guide.exegesis:rhetoric.hebrew.s0.h": { fp: "tuumrn", text: "Leer las tres columnas" },
  "guide.exegesis:rhetoric.hebrew.s1.b": { fp: "1jkdecc", text: "El grupo verde azulado «Poética y estructura» es donde de veras se construye el verso hebreo: el paralelismo en las tres clases de Lowth (sinónimo, antitético, sintético), el quiasmo, la inclusión, el estribillo, el merismo y el acróstico. Varios de ellos —los acrósticos sobre todo— no dejan rastro en una traducción, así que quien solo tiene la traducción no puede verlos." },
  "guide.exegesis:rhetoric.hebrew.s1.h": { fp: "imzjhr", text: "Poética hebrea" },
  "guide.exegesis:rhetoric.hebrew.s2.b": { fp: "1j2f8rl", text: "Nombrar una figura no es el final del trabajo, pero suele ser el comienzo: reconocer que una construcción es deliberada y no incidental cambia lo que crees que el escritor está haciendo con ella." },
  "guide.exegesis:rhetoric.hebrew.s2.h": { fp: "zc26en", text: "Para qué sirve" },
  "guide.exegesis:rhetoric.lede": { fp: "1eei9ae", text: "Las figuras retóricas que operan en un pasaje, con el comentario de Bengel al lado." },
  "guide.exegesis:rhetoric.s0.b": { fp: "71a6sk", text: "El pasaje va a la izquierda, las figuras identificadas en él en el centro y una explicación a la derecha. Las figuras siguen la clasificación de Bullinger y están agrupadas por tipo, de modo que los recursos emparentados quedan juntos." },
  "guide.exegesis:rhetoric.s0.h": { fp: "tuumrn", text: "Leer las tres columnas" },
  "guide.exegesis:rhetoric.s1.b": { fp: "7tynx5", text: "Nombrar una figura no es el final del trabajo, pero suele ser el comienzo: reconocer que una construcción es deliberada y no incidental cambia lo que crees que el autor está haciendo con ella." },
  "guide.exegesis:rhetoric.s1.h": { fp: "zc26en", text: "Para qué sirve" },
  "guide.exegesis:rhetoric.title": { fp: "1s1oyy5", text: "Exégesis · Retórica" },
  "guide.exegesis:synopsis.hebrew.lede": { fp: "3r59mh", text: "Samuel-Reyes junto a Crónicas, con los cambios editoriales del Cronista marcados." },
  "guide.exegesis:synopsis.hebrew.s0.b": { fp: "avuinz", text: "Ancla un pasaje con un paralelo —casi todo Samuel y Reyes, los salmos duplicados, Isaías 36-39, Jeremías 52— y los relatos aparecen en columnas de hebreo vocalizado. Aquí empieza la crítica de la redacción del Antiguo Testamento: lo que el Cronista añade, quita o reformula se ve de inmediato, en vez de reconstruirse de memoria." },
  "guide.exegesis:synopsis.hebrew.s0.h": { fp: "1kkqjul", text: "Comparar relatos" },
  "guide.exegesis:synopsis.hebrew.s1.b": { fp: "1gchawy", text: "El modo de comparación marca cada palabra como conservada, añadida, omitida, sustituida o desplazada, e informa qué proporción de la redacción de la fuente se conserva, lo que convierte la impresión de que «el Cronista suavizó esto» en algo medible." },
  "guide.exegesis:synopsis.hebrew.s1.h": { fp: "5uzop3", text: "Cambios editoriales" },
  "guide.exegesis:synopsis.lede": { fp: "j0cer1", text: "Los paralelos evangélicos uno al lado del otro, con los cambios editoriales marcados." },
  "guide.exegesis:synopsis.s0.b": { fp: "2vmyng", text: "Añade los pasajes paralelos y los relatos aparecen en columnas. La comparación es donde empieza la crítica de la redacción: lo que un evangelista añade, quita o reformula se ve de inmediato, en vez de reconstruirse de memoria." },
  "guide.exegesis:synopsis.s0.h": { fp: "1kkqjul", text: "Comparar relatos" },
  "guide.exegesis:synopsis.s1.b": { fp: "jq9iqt", text: "El modo de comparación marca la clase de cambio que se está haciendo e informa qué proporción de la redacción se conserva, lo que convierte la impresión de que «Mateo apretó esto» en algo medible." },
  "guide.exegesis:synopsis.s1.h": { fp: "5uzop3", text: "Cambios editoriales" },
  "guide.exegesis:synopsis.title": { fp: "1y2a1lt", text: "Exégesis · Sinopsis" },
  "guide.exegesis:variants.hebrew.lede": { fp: "2zcpqz", text: "El texto masorético junto a las versiones antiguas, versículo por versículo." },
  "guide.exegesis:variants.hebrew.s0.b": { fp: "1jojv6u", text: "Para el Antiguo Testamento la comparación es versional: el hebreo junto a la Septuaginta, el targum cuando lo hay incorporado (el Pentateuco e Isaías) y un control en inglés. Cuando una versión difiere del hebreo que tienes delante, puede estar atestiguando un texto hebreo distinto: esa observación es el comienzo de la crítica textual del Antiguo Testamento." },
  "guide.exegesis:variants.hebrew.s0.h": { fp: "rzv62g", text: "Qué estás viendo" },
  "guide.exegesis:variants.hebrew.s1.b": { fp: "i54jj6", text: "En unos pocos libros —Salmos, Jeremías, Job, Ester, Daniel— la versificación de la Septuaginta diverge de verdad, y la vista lo advierte cuando estás en uno de ellos. Ahí las filas se emparejan por número, no necesariamente por contenido: lee las columnas como textos, no como un alineamiento." },
  "guide.exegesis:variants.hebrew.s1.h": { fp: "1e931ej", text: "Una advertencia sobre la numeración de versículos" },
  "guide.exegesis:variants.hebrew.s2.b": { fp: "x8wxcz", text: "Un aparato de manuscritos como el que trae impreso la BHS sigue bajo derechos de autor y no se reproduce aquí. Lo que ves son textos antiguos completos en paralelo, que es además por donde empieza de verdad un primer curso." },
  "guide.exegesis:variants.hebrew.s2.h": { fp: "1dwwaxu", text: "Lo que esto no es" },
  "guide.exegesis:variants.lede": { fp: "1gbmbat", text: "Lo que leen realmente los manuscritos, testigo por testigo." },
  "guide.exegesis:variants.s0.b": { fp: "149e55r", text: "Cada fila es un manuscrito y cada columna un punto de variación, al estilo de una colación de Swanson. Los datos cubren los unciales y noventa papiros. Al hacer clic en un testigo se te dice qué es, de cuándo data y por qué importa: vale la pena, porque el peso de una lectura depende por completo de quién la sostiene." },
  "guide.exegesis:variants.s0.h": { fp: "fj9t9f", text: "Leer la colación" },
  "guide.exegesis:variants.s1.b": { fp: "1pqeula", text: "Normalmente el texto del manuscrito se muestra en forma legible y acentuada. La vista diplomática lo muestra tal como fue transcrito —desnudo, sin acentos, con la sigma medial—, que es lo que se quiere cuando la pregunta es sobre la escritura misma y no sobre las palabras." },
  "guide.exegesis:variants.s1.h": { fp: "1u8dskw", text: "Vista diplomática" },
  "guide.exegesis:variants.title": { fp: "yrl0l9", text: "Exégesis · Variantes" },
  "guide.exegesis:workspace.hebrew.lede": { fp: "zpr59j", text: "Analiza un pasaje hebreo palabra por palabra y escribe tu propia traducción." },
  "guide.exegesis:workspace.hebrew.s0.b": { fp: "f2626r", text: "A cada palabra puedes darle su análisis —conjugación, tema, persona, género, número, con la abreviatura que use tu curso— y su función sintáctica, y cada versículo tiene un cuadro para tu traducción. Los campos son texto libre: la aplicación ya sabe analizar cada palabra, así que lo que esta vista registra es tu lectura del pasaje, no la suya." },
  "guide.exegesis:workspace.hebrew.s0.h": { fp: "zihcfl", text: "Qué se hace aquí" },
  "guide.exegesis:workspace.hebrew.s1.b": { fp: "wjplt4", text: "Al hacer clic en una palabra aparece su análisis de diccionario según el texto etiquetado, así puedes comprobar tu respuesta después de haberte comprometido con una. Los versículos van de derecha a izquierda, como debe ser; tus anotaciones quedan junto a la palabra a la que pertenecen." },
  "guide.exegesis:workspace.hebrew.s1.h": { fp: "1kpz3wm", text: "Ayuda para leer" },
  "guide.exegesis:workspace.hebrew.s2.b": { fp: "z3f8p4", text: "Con la sesión iniciada, el trabajo se puede guardar y retomar después, y un pasaje terminado se puede exportar en PDF para entregarlo o imprimirlo." },
  "guide.exegesis:workspace.hebrew.s2.h": { fp: "y6ji3g", text: "Guardar tu trabajo" },
  "guide.exegesis:workspace.lede": { fp: "7ti8y0", text: "Analiza un pasaje palabra por palabra y escribe tu propia traducción." },
  "guide.exegesis:workspace.s0.b": { fp: "c0shnm", text: "A cada palabra puedes darle su análisis y su función sintáctica, y cada versículo tiene un cuadro para tu traducción. Lo importante es hacerlo: la aplicación ya sabe analizar cada palabra, así que lo que esta vista registra es tu lectura del pasaje, no la suya." },
  "guide.exegesis:workspace.s0.h": { fp: "zihcfl", text: "Qué se hace aquí" },
  "guide.exegesis:workspace.s1.b": { fp: "1x24j1e", text: "Puedes mostrar glosas para las palabras por debajo de la frecuencia que elijas, de modo que se te dé el vocabulario que aún no has visto y no el que ya deberías saber. Ponla alta al empezar y bájala a medida que crezca tu vocabulario." },
  "guide.exegesis:workspace.s1.h": { fp: "1d375z9", text: "Glosas" },
  "guide.exegesis:workspace.s2.b": { fp: "z3f8p4", text: "Con la sesión iniciada, el trabajo se puede guardar y retomar después, y un pasaje terminado se puede exportar en PDF para entregarlo o imprimirlo." },
  "guide.exegesis:workspace.s2.h": { fp: "y6ji3g", text: "Guardar tu trabajo" },
  "guide.exegesis:workspace.title": { fp: "4ziaps", text: "Exégesis · Sintaxis" },
  "guide.grammar.g0.does": { fp: "1no487s", text: "Toca un término subrayado con puntos" },
  "guide.grammar.g0.gets": { fp: "1en0c3g", text: "una definición en español llano de ese término gramatical" },
  "guide.grammar.g1.does": { fp: "rg03u6", text: "Toca palabras contiguas en un ejercicio" },
  "guide.grammar.g1.gets": { fp: "g7b504", text: "las respuestas se revelan una a una: márcate bien o mal y el bloque guarda tu puntaje en este dispositivo" },
  "guide.grammar.hebrew.lede": { fp: "1i3oxzb", text: "Una gramática hebrea completa de primer año, del alfabeto a los verbos débiles." },
  "guide.grammar.hebrew.r0": { fp: "1ipypwq", text: "Vocabulario: el mazo de hebreo" },
  "guide.grammar.hebrew.r1": { fp: "n2kiix", text: "Lector: las formas en el texto" },
  "guide.grammar.hebrew.s0.b": { fp: "oommmk", text: "Los capítulos siguen el orden habitual de un primer año: la escritura y la vocalización, el sistema nominal (artículo, preposiciones, estado constructo, sufijos) y luego el verbo: primero el qal, el waw consecutivo que sostiene toda la narración, y cada conjugación derivada por turno, con los verbos débiles y un capítulo de sintaxis para cerrar. Aquí no hay selector de nivel; cómo encajan los capítulos en tu curso lo decide tu profesor." },
  "guide.grammar.hebrew.s0.h": { fp: "111deg6", text: "Un texto, veintidós capítulos" },
  "guide.grammar.hebrew.s1.b": { fp: "1apgtq7", text: "Cada paradigma se presenta con las terminaciones marcadas, y casi todos los capítulos terminan con ejercicios de análisis que se revelan al tocarlos. El vocabulario del análisis —conjugación, tema, persona, género, número— es exactamente el que usan el panel de análisis del Lector y los cuestionarios de morfología, así que aquí nada hay que traducir de una herramienta a otra." },
  "guide.grammar.hebrew.s1.h": { fp: "1i2knl2", text: "Paradigmas y ejercicios" },
  "guide.grammar.hebrew.s2.b": { fp: "9r7l1t", text: "El capítulo de los verbos débiles se organiza en torno a una sola tabla de referencia: cada clase con su perfecto, su imperfecto, su wayyiqtol y su infinitivo uno al lado del otro. Está pensada para volver a ella, no para memorizarla; los cinco verbos narrativos que aparecen debajo son los que conviene sobreaprender." },
  "guide.grammar.hebrew.s2.h": { fp: "182r256", text: "La tabla de los verbos débiles" },
  "guide.grammar.hebrew.title": { fp: "5vj8i3", text: "Gramática hebrea" },
  "guide.grammar.lede": { fp: "1ijnmnc", text: "Una gramática griega completa, del alfabeto a los verbos en -μι, escrita en dos niveles." },
  "guide.grammar.r0": { fp: "g9669a", text: "Vocabulario: las palabras que acompañan a las formas" },
  "guide.grammar.r1": { fp: "1qsrcv2", text: "Lector: ver las formas en texto corrido" },
  "guide.grammar.s0.b": { fp: "o3oser", text: "El selector de nivel cambia lo que muestra la página, no solo cuánto. Principiante te da el punto de partida desde la gramática española, los paradigmas, los ejemplos explicados y los ejercicios. Intermedio quita los ejercicios y añade las categorías sintácticas —las funciones que puede tener cada forma, según Wallace— además de una sección final sobre las cuestiones de interpretación que plantean las formas. Tu elección se recuerda." },
  "guide.grammar.s0.h": { fp: "15d1qgq", text: "Principiante e Intermedio" },
  "guide.grammar.s1.b": { fp: "g98rrz", text: "La pestaña Mínimos reúne los ocho conjuntos de paradigmas que más rinden: domina estos y buena parte del Nuevo Testamento se vuelve legible. Vale la pena volver a ellos mucho después de haberlos dejado atrás." },
  "guide.grammar.s1.h": { fp: "2rel0s", text: "Mínimos" },
  "guide.grammar.s2.b": { fp: "vrmoe7", text: "En Principiante, casi todos los capítulos traen ejercicios con respuesta inmediata, oraciones tomadas de clase y un ejemplo guiado que se revela paso a paso. El control «Ponme a prueba» dentro de un ejercicio borra la tabla que está evaluando, para que respondas de memoria y no leyendo hacia arriba." },
  "guide.grammar.s2.h": { fp: "1tlbcsw", text: "Práctica" },
  "guide.grammar.s3.b": { fp: "186n6x3", text: "Cada capítulo termina con enlaces al Nuevo Testamento etiquetado: cada sustantivo en genitivo, cada participio aoristo, y así. Se abren como una búsqueda junto al capítulo en vez de llevarte a otra página, para que puedas comprobar una afirmación sin perder el hilo." },
  "guide.grammar.s3.h": { fp: "19saywv", text: "Verlo en un texto real" },
  "guide.grammar.title": { fp: "yegg4e", text: "Gramática" },
  "guide.map.lede": { fp: "13unsv", text: "Dónde dicen los autores de la biblioteca que ocurrieron las cosas: todos los lugares que nombran, en un solo mapa." },
  "guide.map.r0": { fp: "bvtgxj", text: "Textos: las obras de donde salen estos lugares" },
  "guide.map.s0.b": { fp: "1tq8klg", text: "Los nombres de lugar etiquetados en la biblioteca de Textos, con el número de veces que se menciona cada uno. Los puntos se dibujan según la frecuencia con que aparece cada lugar, así que la forma del mundo de un autor se ve antes de leer una sola línea suya." },
  "guide.map.s0.h": { fp: "1qeojud", text: "Qué está trazado" },
  "guide.map.s1.b": { fp: "12ilzsz", text: "Filtra por autor para ver la geografía de un solo escritor —la Judea de Josefo frente al Egeo de Heródoto— o busca un lugar por su nombre. Acerca y desplaza para moverte; «Restablecer» vuelve al mapa completo." },
  "guide.map.s1.h": { fp: "1bfqsj1", text: "Acotar" },
  "guide.map.s2.b": { fp: "14x2trf", text: "Toca un lugar para ver cuántas veces se menciona y un enlace que lo busca en la biblioteca, de modo que pasas del punto a las frases que hay detrás." },
  "guide.map.s2.h": { fp: "x8v8ba", text: "Del lugar a los pasajes" },
  "guide.map.title": { fp: "1amg5z1", text: "Lugares" },
  "guide.notes.lede": { fp: "1jjc2hs", text: "Todo lo que has escrito, en un solo cuaderno: notas de versículo, resaltados y notas al margen de todas las partes de la aplicación." },
  "guide.notes.r0": { fp: "os0kgk", text: "Lector: donde se escriben casi todas las notas" },
  "guide.notes.r1": { fp: "4ad9gn", text: "Exégesis: el cuaderno del taller" },
  "guide.notes.s0.b": { fp: "12jt9jy", text: "Una nota hecha sobre un versículo en el Lector, en el taller de exégesis, sobre un texto de trasfondo o en un capítulo de Gramática llega toda aquí. Las notas se mantienen al día entre las pestañas abiertas, así que una nota escrita en un sitio aparece en otro sin recargar." },
  "guide.notes.s0.h": { fp: "diy3c1", text: "Un cuaderno, muchas superficies" },
  "guide.notes.s1.b": { fp: "1b4slj2", text: "Las notas se pueden archivar en carpetas y buscar. Cada una conserva su referencia, así que al abrirla vuelves al pasaje sobre el que se escribió." },
  "guide.notes.s1.h": { fp: "85n6lv", text: "Volver a encontrar una nota" },
  "guide.notes.title": { fp: "4f76ga", text: "Notas" },
  "guide.reader.g0.does": { fp: "1kkdwtu", text: "Pasar el cursor sobre una palabra" },
  "guide.reader.g0.gets": { fp: "1xyehut", text: "entrada léxica, análisis y glosas en el panel de abajo" },
  "guide.reader.g1.does": { fp: "1xakelj", text: "Mayús" },
  "guide.reader.g1.gets": { fp: "1p2g95c", text: "fija el panel de análisis en la palabra actual; Mayús otra vez lo suelta" },
  "guide.reader.g2.does": { fp: "l2yua1", text: "Clic derecho sobre una palabra" },
  "guide.reader.g2.gets": { fp: "14fgq4", text: "categorías sintácticas, además de opciones de búsqueda para esa palabra" },
  "guide.reader.g3.does": { fp: "10n782i", text: "⌘K / Ctrl-K" },
  "guide.reader.g3.gets": { fp: "1yjt7z1", text: "buscar en todos los corpus y traducciones" },
  "guide.reader.lede": { fp: "25jap0", text: "Lee griego o hebreo corrido con el léxico, el análisis morfológico y la sintaxis a un clic." },
  "guide.reader.r0": { fp: "avmkxy", text: "Gramática: los paradigmas detrás del análisis" },
  "guide.reader.r1": { fp: "1qtpan3", text: "Exégesis: trabajar un pasaje a fondo" },
  "guide.reader.s0.b": { fp: "sf0pms", text: "Escribe una referencia en el cuadro de búsqueda: «Juan 3:16», «Rom 8» o «Mat 5:3-12» funcionan igual. Si en cambio escribes una palabra griega, la busca; y los botones NT / LXX / BH cambian el corpus que estás leyendo. El texto se sigue cargando a medida que desplazas, así que puedes leer más allá del final de un capítulo sin hacer nada." },
  "guide.reader.s0.h": { fp: "ffsvyp", text: "Encontrar un pasaje" },
  "guide.reader.s1.b": { fp: "1fsjjfd", text: "Al pasar el cursor sobre cualquier palabra, el panel de abajo se llena con su entrada léxica, su análisis y sus glosas. Ese panel sigue al cursor, lo cual es útil mientras se lee y molesto mientras se escribe: pulsa Mayús para fijarlo en la palabra que estás mirando, y Mayús otra vez para soltarlo." },
  "guide.reader.s1.h": { fp: "128l6lu", text: "Entender una palabra" },
  "guide.reader.s2.b": { fp: "1li337a", text: "Hacer clic derecho sobre una palabra abre sus categorías sintácticas, tomadas de cuatro bancos de árboles independientes: Wallace, PROIEL, GBI y la base de datos sintáctica de la ABS. No coinciden entre sí, y en eso está la gracia: donde difieren, la construcción es realmente discutida. Puedes desactivar fuentes concretas en el menú si la comparación estorba más de lo que ayuda." },
  "guide.reader.s2.h": { fp: "1rp7gfm", text: "Sintaxis" },
  "guide.reader.s3.b": { fp: "1nwr1bp", text: "El selector de traducción añade una traducción junto al griego o debajo de él. La Berean Standard Bible está alineada palabra por palabra con el Nuevo Testamento griego; las demás aparecen versículo por versículo. Si eliges «Solo griego», desaparece de nuevo." },
  "guide.reader.s3.h": { fp: "zase69", text: "Leer con una traducción" },
  "guide.reader.title": { fp: "1evlkqn", text: "El Lector" },
  "guide.register.g0.does": { fp: "ik4pcb", text: "Tab o →" },
  "guide.register.g0.gets": { fp: "1xzormi", text: "acepta la parte gris que completa el cuadro de referencia" },
  "guide.register.g1.does": { fp: "1mkkihy", text: "Toca un resultado" },
  "guide.register.g1.gets": { fp: "sj777s", text: "abre la evidencia: qué comparten los dos textos y en qué se diferencian" },
  "guide.register.g2.does": { fp: "bewfpv", text: "Toca el encabezado de una columna" },
  "guide.register.g2.gets": { fp: "3powmw", text: "explica qué es esa columna" },
  "guide.register.lede": { fp: "f34l27", text: "Descubre qué obras de la biblioteca escriben un griego como el que estás leyendo, y ve exactamente qué las hace parecidas." },
  "guide.register.r0": { fp: "1sgla8", text: "De dónde vienen estas mediciones" },
  "guide.register.r1": { fp: "1a716tg", text: "Textos: leer las obras que se comparan" },
  "guide.register.r2": { fp: "1p63buk", text: "Búsqueda de construcciones: encontrar las construcciones que esto cuenta" },
  "guide.register.s0.b": { fp: "1ves6bq", text: "El registro es el nivel y la textura del griego: con cuánta frecuencia un autor recurre a los participios, a las partículas, al artículo, a la subordinación. No es la autoría. Obras del mismo género suelen puntuar parecido las escriba quien las escriba —aquí Hebreos queda en primer lugar frente a Romanos—, así que lee una posición alta como «se leen de forma parecida» y deja que la tabla de cada resultado te diga por qué." },
  "guide.register.s0.h": { fp: "11ug5y3", text: "Qué mide y qué no mide" },
  "guide.register.s1.b": { fp: "z309o7", text: "Para la Escritura, escribe una referencia: «Marcos», «Lucas 1-2» o «Marcos 4:1-9» funcionan igual, en español o en inglés, y el cuadro completa la perícopa mientras escribes. Para lo demás, elige un título de la lista de la biblioteca que está debajo del cuadro. Un libro entero se responde al instante; un pasaje se analiza en el momento." },
  "guide.register.s1.h": { fp: "kdez7z", text: "Elegir qué comparar" },
  "guide.register.s2.b": { fp: "12mhytm", text: "Una obra entera promedia su propia variedad hasta hacerla desaparecer. Lucas 3-24 queda con Mateo, Marcos y Hechos: el registro sinóptico. Lucas 1-2 queda con 1 Reyes, Judit, Tobías y Daniel: la narración de la infancia se septuagintiza, y comparar las dos mitades es la manera de verlo ocurrir." },
  "guide.register.s2.h": { fp: "jtwy3o", text: "Los pasajes son lo interesante" },
  "guide.register.s3.b": { fp: "1reaesv", text: "Palabras comunes compara con cuánta frecuencia usa cada texto las 150 palabras más frecuentes de toda la biblioteca —en su mayoría las gramaticales—, de modo que sigue cómo se construye una oración. Sintaxis compara la frecuencia de cada construcción. Palabras temáticas compara el vocabulario que NO está entre esas 150 comunes, así que se acerca tanto a de qué trata un texto como a cómo está escrito. Cada resultado se explica en los términos de la lente que elegiste." },
  "guide.register.s3.h": { fp: "1z0ma2h", text: "Tres maneras de medir" },
  "guide.register.s4.b": { fp: "9nfbyc", text: "Toda cifra es una frecuencia por cada 1000 palabras, para que textos de longitudes muy distintas puedan ponerse uno junto a otro. La distancia es la diferencia media entre dos perfiles: 0 es idéntico, y alrededor de 1,0 no es más parecido que dos obras tomadas al azar. La barra usa una escala fija, así que un primer resultado con la barra corta te está diciendo que la obra no tiene parientes cercanos en toda la biblioteca. Cualquier encabezado de columna se explica solo si lo tocas." },
  "guide.register.s4.h": { fp: "pmmleu", text: "Leer las cifras" },
  "guide.register.s5.b": { fp: "1v3tl30", text: "Las dos últimas columnas dicen qué hace ese mismo rasgo en la prosa ática clásica y en el griego de la época helenística, para que puedas juzgar si una cifra es llamativa. Por defecto toman el género del texto que estás comparando —un evangelio contra la narrativa, una carta contra las cartas— y puedes fijar cualquier otro conjunto para ver si una costumbre pertenece al género o al griego en general. Cuando la biblioteca no tiene nada de un género en un periodo, la columna lo dice en vez de sustituirlo por un promedio: aquí no hay ninguna epistolografía clásica." },
  "guide.register.s5.h": { fp: "7ddvbd", text: "Clásico y koiné, por género" },
  "guide.register.s6.b": { fp: "1wqyfc8", text: "Encima de la clasificación, el texto que estás comparando se sitúa en dos escalas sobre las que la investigación ya venía discutiendo. La periodicidad es la distinción de Aristóteles entre el estilo «ensartado», cuyas oraciones simplemente se van añadiendo, y el estilo periódico, cuyas oraciones se pliegan unas en otras; la inclinación clásica es dónde queda el texto entre el perfil clásico medio y el koiné medio. Discrepan de maneras útiles —Hebreos es el libro más periódico del Nuevo Testamento y aun así se inclina más lejos del ático que Juan— y la nota que hay detrás explica por qué." },
  "guide.register.s6.h": { fp: "a1ws9", text: "Dos ejes con nombre" },
  "guide.register.s7.b": { fp: "mc1nfb", text: "«Imprimir / guardar en PDF» produce un documento, no una captura de pantalla: la clasificación completa, la evidencia de los primeros paralelos con referencias de versículo para cada rasgo compartido, el método, y la edición y la morfología detrás de cada texto citado. La dirección web lleva lo que estés viendo, así que una comparación se le puede enviar a una clase." },
  "guide.register.s7.h": { fp: "2aq4w", text: "Llevártelo" },
  "guide.register.title": { fp: "avtc68", text: "Registro" },
  "guide.search.g0.does": { fp: "10n782i", text: "⌘K / Ctrl-K" },
  "guide.search.g0.gets": { fp: "1cdbp2i", text: "abre la búsqueda desde cualquier parte de la aplicación" },
  "guide.search.g1.does": { fp: "l2jcuq", text: "Clic derecho sobre una palabra en el Lector" },
  "guide.search.g1.gets": { fp: "7ymbia", text: "busca esa palabra o su lema sin volver a escribirla" },
  "guide.search.lede": { fp: "cnae2d", text: "Una sola búsqueda en el Nuevo Testamento griego, la Septuaginta, las traducciones y la biblioteca de trasfondo." },
  "guide.search.r0": { fp: "q7ovvc", text: "Búsqueda de construcciones: buscar por gramática y no por palabra" },
  "guide.search.s0.b": { fp: "8r8i98", text: "Una palabra griega, una palabra en español, una frase entre comillas o una referencia. Las pestañas sobre los resultados muestran cuántos aciertos tiene cada corpus, así que ves de un vistazo si una palabra es común en el Nuevo Testamento pero rara en la Septuaginta, que suele ser el dato más interesante." },
  "guide.search.s0.h": { fp: "g5pxey", text: "Qué puedes escribir" },
  "guide.search.s1.b": { fp: "1kmkw6v", text: "Escribe en Beta Code y se convierte sobre la marcha: «logos» se vuelve λογος. Esto funciona en toda la aplicación, no solo aquí." },
  "guide.search.s1.h": { fp: "7474e6", text: "Escribir griego sin teclado griego" },
  "guide.search.s2.b": { fp: "1riylw8", text: "El selector de alcance limita la búsqueda a un corpus, a una traducción o a una colección de trasfondo, y además puedes restringirla a libros concretos. El deslizador de contexto de cada resultado amplía los versículos de alrededor, cruzando los límites de capítulo cuando hace falta." },
  "guide.search.s2.h": { fp: "sqnnqe", text: "Acotar" },
  "guide.search.s3.b": { fp: "m0t0uc", text: "La búsqueda se abre como un panel junto a lo que estabas leyendo, para que los resultados puedan compararse con el pasaje que los motivó. La página completa sigue existiendo para los enlaces directos y para las sesiones largas." },
  "guide.search.s3.h": { fp: "5e3vf4", text: "Dónde se abre" },
  "guide.search.title": { fp: "1j0itop", text: "Búsqueda" },
  "guide.texts.lede": { fp: "1zgzwq", text: "La biblioteca de trasfondo: Josefo, Filón, los Padres apostólicos, los targumes, la Misná, los autores grecorromanos y más." },
  "guide.texts.r0": { fp: "hwyob7", text: "Exégesis → Trasfondo: ver cuáles de estos cita un versículo" },
  "guide.texts.s0.b": { fp: "ln3t3l", text: "El menú Textos se abre por categoría, luego por autor cuando una categoría tiene varios, y luego por obra. Una vez abierta una obra, al hacer clic en su título se despliega una cascada de libro, capítulo y versículo para saltar a un pasaje concreto." },
  "guide.texts.s0.h": { fp: "mpdjba", text: "Encontrar una obra" },
  "guide.texts.s1.b": { fp: "2qp5eq", text: "Cuando una obra tiene ambos, el selector de vista alterna entre el original, la traducción o los dos en columnas paralelas. No todas las obras tienen texto griego: algunas están solo en traducción porque no había una edición del original en dominio público." },
  "guide.texts.s1.h": { fp: "1ntszuo", text: "Griego e inglés juntos" },
  "guide.texts.s2.b": { fp: "1horjxd", text: "Busca dentro de la obra abierta para encontrar una frase, y usa el Resumen para orientarte en una obra que no has leído antes. Donde el texto griego está etiquetado, al hacer clic en una palabra obtienes su análisis igual que en el Lector." },
  "guide.texts.s2.h": { fp: "1izwawg", text: "Leer alrededor de una cita" },
  "guide.texts.title": { fp: "1s10onr", text: "Textos" },
  "guide.themes.lede": { fp: "n4yv4", text: "Un índice temático de la biblioteca de trasfondo: lo que las fuentes antiguas dicen realmente sobre la resurrección, la pureza, el sábado y lo demás." },
  "guide.themes.r0": { fp: "fwpl1k", text: "Textos: leer las fuentes completas" },
  "guide.themes.r1": { fp: "1623j1u", text: "Búsqueda: encontrar una palabra en toda la biblioteca" },
  "guide.themes.s0.b": { fp: "1b9shhw", text: "La biblioteca de Textos ya se puede recorrer por autor y buscar por palabra. Este es el eje por el que suele empezar una pregunta de seminario: por tema. Elige un tema y obtienes los pasajes que lo tocan, agrupados y resumidos, y cada uno se abre en el lector." },
  "guide.themes.s0.h": { fp: "138g080", text: "La tercera vía de entrada a la biblioteca" },
  "guide.themes.s1.b": { fp: "wcbx9c", text: "Cada cita la devolvió una búsqueda real del corpus y luego se comprobó contra el texto; ninguna se recuerda de memoria. Los resúmenes los redacta una máquina a partir del pasaje mismo y se revisan a mano, y la página lo dice." },
  "guide.themes.s1.h": { fp: "8u25do", text: "De dónde salen los pasajes" },
  "guide.themes.s2.b": { fp: "vb8w96", text: "Cada tema termina con las ausencias: posturas que cabría esperar encontrar y no aparecen. Esta es la parte que una búsqueda por palabra no puede darte, y para un trabajo escrito suele ser la mitad más útil." },
  "guide.themes.s2.h": { fp: "yzvojt", text: "Lo que las fuentes no dicen" },
  "guide.themes.title": { fp: "1h2ekoj", text: "Temas" },
  "guide.vocab.lede": { fp: "1a172zi", text: "Tarjetas y cuestionarios de griego y hebreo, ordenados por la frecuencia real de cada palabra." },
  "guide.vocab.r0": { fp: "mdd1i8", text: "Gramática: las formas en que aparecen estas palabras" },
  "guide.vocab.s0.b": { fp: "147jlgs", text: "Las palabras se agrupan por frecuencia, así que las primeras secciones son las que rinden más rápido: el puñado de palabras que forma buena parte de cada página. Recorrer la lista en orden suele dar mejor resultado que elegir las secciones que parecen interesantes." },
  "guide.vocab.s0.h": { fp: "1aqrvbk", text: "Cómo está ordenado el mazo" },
  "guide.vocab.s1.b": { fp: "157ipz0", text: "El selector de idioma cambia el mazo entero entre griego y hebreo. Se llevan por separado, de modo que avanzar en uno no altera el otro." },
  "guide.vocab.s1.h": { fp: "12281p", text: "Griego y hebreo" },
  "guide.vocab.s2.b": { fp: "z15a97", text: "Un cuestionario puede tomar una parte de sus preguntas de secciones que ya terminaste. Eso es lo que impide que el vocabulario anterior se desdibuje mientras aprendes palabras nuevas, y conviene dejarlo activado aunque haga cada cuestionario un poco más difícil." },
  "guide.vocab.s2.h": { fp: "tnr3lt", text: "Repaso" },
  "guide.vocab.title": { fp: "7ubpux", text: "Vocabulario" },
}
